'use strict';
const $=id=>document.getElementById(id), frame=$('editor');
const fonts={sans:'"Noto Sans", "Noto Sans SC", "Noto Sans JP", "Microsoft YaHei", sans-serif',serif:'"Noto Serif", "Noto Serif SC", "Songti SC", SimSun, serif',system:'Arial, "PingFang SC", "Microsoft YaHei", sans-serif'};
let settings={mt:18,mb:18,ml:20,mr:20,line:1.5,gap:18,cjk:true,columns:1,font:'sans',size:11},zoom=.85,range=null,history=[],historyIndex=-1,dirty=false,selected=-1,dragIndex=-1,saveTimer;
const defaultCSS=`@import url('https://fonts.googleapis.com/css2?family=Noto+Sans:wght@400;500;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap');
#cv-content{color:#344238;font-size:10pt;line-height:1.55}#cv-content h1{font-size:32pt;line-height:1.2;font-weight:600;letter-spacing:-1.4px;margin:0 0 7px;color:#263f35}#cv-content .cn-name{font-size:19pt;font-weight:400;letter-spacing:2px;color:#75816e;margin-left:13px}#cv-content .role{font-size:11pt;color:#6a7e5e;letter-spacing:.3px;margin:0 0 17px}#cv-content .contact{font-size:8pt;line-height:1.8;color:#849078;border-bottom:1px solid #cbd5c3;padding-bottom:22px;margin-bottom:0}#cv-content h2{font-size:9pt;font-weight:600;letter-spacing:1.8px;color:#6d845b;text-transform:uppercase;margin:0 0 12px;display:flex;align-items:center;gap:13px}#cv-content h2:after{content:'';height:1px;background:#e0e6d9;flex:1}#cv-content h2 span{font-size:8pt;font-weight:400;letter-spacing:1px;color:#92a183}#cv-content h3{font-size:10.5pt;font-weight:600;margin:0 0 4px;color:#34472e}#cv-content p{margin:5px 0 9px}#cv-content .date{float:right;font-size:8pt;color:#8b987d;font-weight:400}#cv-content .company{font-size:9pt;color:#7b8e69;margin:0 0 8px}#cv-content ul{padding-left:16px;margin:8px 0 16px}#cv-content li{padding-left:3px;margin:5px 0}#cv-content .skills{display:grid;grid-template-columns:95px 1fr;gap:7px 16px;font-size:9pt}#cv-content .skills b{font-weight:500;color:#607b4f}#cv-content .end-note{font-size:8pt;color:#96a587;margin-top:15px}`;
const sample=`<section><h1>Alex Chen <span class="cn-name">陈安然</span></h1><p class="role">Product Designer · 产品设计师</p><p class="contact">San Francisco, CA &nbsp; / &nbsp; alex.chen@example.com &nbsp; / &nbsp; portfolio.example.com</p></section>
<section><h2>Profile <span>个人简介</span></h2><p>Thoughtful product designer connecting complex systems with everyday human needs. Six years of turning ambiguity into clear, useful experiences for global audiences.</p><p>以人为本，以细节见长。擅长跨文化协作，将复杂问题转化为简洁、自然的数字体验。</p></section>
<section><h2>Experience <span>工作经历</span></h2><h3>Senior Product Designer <span class="date">2022 — Present</span></h3><p class="company">Forma Studio · San Francisco</p><ul><li>Led the redesign of a collaborative workspace used by 40,000+ teams, increasing activation by 28%.</li><li>Built a bilingual design system spanning 60+ components across web and mobile.</li><li>Partnered with research and engineering to bring three products from concept to launch.</li></ul><h3>Product Designer <span class="date">2019 — 2022</span></h3><p class="company">Fieldwork · Shanghai 上海</p><ul><li>Designed end-to-end experiences for a growing creative community of 120,000 members.</li><li>将用户研究融入产品迭代，优化核心流程，使任务完成率提升 35%。</li></ul></section>
<section><h2>Education <span>教育背景</span></h2><h3>BFA, Communication Design <span class="date">2015 — 2019</span></h3><p class="company">California College of the Arts</p><p>Focus on interaction design, visual systems, and cross-cultural communication.</p></section>
<section><h2>Selected skills <span>专业技能</span></h2><div class="skills"><b>Design</b><span>Product strategy · Interaction design · Design systems</span><b>Tools</b><span>Figma · Framer · HTML / CSS</span><b>Languages</b><span>English (fluent) · 中文（母语）</span></div></section>`;
function doc(){return frame.contentDocument}function root(){return doc()?.getElementById('cv-content')}
function pageCSS(print=false){return `html{margin:0!important;padding:0!important;background:white!important}body{margin:0!important;padding:0!important;background:white!important}#cv-page{box-sizing:border-box!important;width:210mm!important;min-height:297mm;padding:${settings.mt}mm ${settings.mr}mm ${settings.mb}mm ${settings.ml}mm!important;margin:0!important;background:white;position:relative}#cv-content{outline:none!important;min-height:20px;font-family:${fonts[settings.font]};font-size:${settings.size}pt;line-height:${settings.line};line-break:${settings.cjk?'strict':'auto'};overflow-wrap:break-word;word-break:normal;column-count:${settings.columns};column-gap:9mm}#cv-content section{margin-bottom:${settings.gap}pt;break-inside:avoid}#cv-content section:last-child{margin-bottom:0}#cv-content h1,#cv-content h2,#cv-content h3{break-after:avoid}#cv-content p,#cv-content li{orphans:2;widows:2}#cv-content img{max-width:100%;height:auto}a{cursor:text} [data-active-section]{outline:1px dashed #b0c6a4;outline-offset:7px}@page{size:A4 portrait;margin:${settings.mt}mm ${settings.mr}mm ${settings.mb}mm ${settings.ml}mm}@media print{html,body{width:auto!important;height:auto!important;overflow:visible!important;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}#cv-page{width:auto!important;min-height:0!important;height:auto!important;padding:0!important;box-shadow:none!important}#cv-content{min-height:0!important}[data-active-section]{outline:none!important}}`;}
function setupHTML(content,styles='',bodyAttrs=''){return `<!doctype html><html lang="en"><head><meta charset="utf-8">${styles}<style id="atelier-page-style">${pageCSS()}</style></head><body><div id="cv-page"><div id="cv-content" ${bodyAttrs} contenteditable="true" spellcheck="false">${content}</div></div></body></html>`}
function load(content,styles,attrs=''){range=null;frame.onload=()=>{const d=doc(),r=root();d.addEventListener('selectionchange',()=>{const s=d.getSelection();if(s.rangeCount&&r.contains(s.anchorNode))range=s.getRangeAt(0).cloneRange()});r.addEventListener('input',()=>{dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{snapshot();refresh()},350);measure()});r.addEventListener('click',e=>{if(e.target.closest('a'))e.preventDefault();let blocks=getBlocks(),index=blocks.findIndex(b=>b===e.target||b.contains(e.target));if(index>=0)selectSection(index,false)});d.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey?1:-1)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();download()}});r.addEventListener('paste',e=>{e.preventDefault();const html=e.clipboardData.getData('text/html');if(html){const p=sanitize(html);d.execCommand('insertHTML',false,p.body.innerHTML)}else d.execCommand('insertText',false,e.clipboardData.getData('text/plain'));setTimeout(()=>{snapshot();refresh()},0)});new ResizeObserver(measure).observe(r);history=[];historyIndex=-1;snapshot();refresh();fit();d.fonts.ready.then(measure);};frame.srcdoc=setupHTML(content,styles,attrs)}
function cleanClone(){const c=root().cloneNode(true);c.querySelectorAll('[data-active-section]').forEach(x=>x.removeAttribute('data-active-section'));return c}
function snapshot(){if(!root())return;const s=JSON.stringify({html:cleanClone().innerHTML,style:root().getAttribute('style')||'',settings});if(history[historyIndex]===s)return;history=history.slice(0,historyIndex+1);history.push(s);if(history.length>100)history.shift();historyIndex=history.length-1;updateUndo()}
function flush(){clearTimeout(saveTimer);snapshot()}
function undo(dir){flush();const next=historyIndex+dir;if(next<0||next>=history.length)return;historyIndex=next;const s=JSON.parse(history[next]);root().innerHTML=s.html;root().setAttribute('style',s.style);settings=s.settings;range=null;dirty=true;applySettings(false);refresh();updateUndo()}
function updateUndo(){$('undo').disabled=historyIndex<=0;$('redo').disabled=historyIndex>=history.length-1}
function restore(){frame.contentWindow.focus();if(range&&root().contains(range.commonAncestorContainer)){const s=doc().getSelection();s.removeAllRanges();s.addRange(range)}return doc().getSelection()}
function command(cmd,value){flush();restore();doc().execCommand(cmd,false,value);dirty=true;snapshot();refresh()}
function styleText(property,value){flush();const s=restore();if(s&&!s.isCollapsed&&root().contains(s.anchorNode)){doc().execCommand('styleWithCSS',false,true);if(property==='fontFamily')doc().execCommand('fontName',false,value);else if(property==='color')doc().execCommand('foreColor',false,value);else{doc().execCommand('fontSize',false,'7');root().querySelectorAll('font[size="7"],span[style*="xxx-large"]').forEach(el=>{el.removeAttribute('size');el.style.fontSize=value})}}else{root().style[property]=value;if(property==='fontSize')root().querySelectorAll('p,li,td,.skills').forEach(x=>x.style.fontSize=value)}dirty=true;snapshot();measure()}
function getBlocks(){const r=root();let b=[...r.children];if(b.length===1&&b[0].children.length>1&&!/^(P|H[1-6]|UL|OL|TABLE)$/.test(b[0].tagName))b=[...b[0].children];return b.filter(x=>!['STYLE','LINK','SCRIPT'].includes(x.tagName))}
function labelFor(b,i){const h=b.querySelector('h1,h2,h3');return (h?.textContent||b.textContent||`Section ${i+1}`).trim().slice(0,38)}
function refresh(){const list=$('sections');list.replaceChildren();getBlocks().forEach((b,i)=>{const item=document.createElement('div');item.className='section-item'+(i===selected?' active':'');item.draggable=true;item.innerHTML='<span class="handle" aria-hidden="true">⠿</span>';const button=document.createElement('button');button.className='section-name';button.textContent=labelFor(b,i);button.title=button.textContent;button.onclick=()=>selectSection(i,true);item.append(button);for(const [direction,label] of [[-1,'↑'],[1,'↓']]){const m=document.createElement('button');m.className='move';m.textContent=label;m.setAttribute('aria-label',`${direction<0?'Move up':'Move down'} ${button.textContent}`);m.onclick=()=>moveSection(i,i+direction);item.append(m)}item.ondragstart=e=>{dragIndex=i;e.dataTransfer.setData('text/plain',String(i));e.dataTransfer.effectAllowed='move'};item.ondragover=e=>{e.preventDefault();item.classList.add('drag-over')};item.ondragleave=()=>item.classList.remove('drag-over');item.ondrop=e=>{e.preventDefault();item.classList.remove('drag-over');if(dragIndex>=0)moveSection(dragIndex,i);dragIndex=-1};item.ondragend=()=>dragIndex=-1;list.append(item)});measure()}
function selectSection(i,scroll){selected=i;root().querySelectorAll('[data-active-section]').forEach(x=>x.removeAttribute('data-active-section'));const b=getBlocks()[i];if(!b)return;b.setAttribute('data-active-section','');if(scroll){const y=b.getBoundingClientRect().top*zoom; $('canvas').scrollTo({top:Math.max(0,y-60),behavior:'smooth'});frame.contentWindow.focus();const r=doc().createRange();r.selectNodeContents(b);r.collapse(true);const s=doc().getSelection();s.removeAllRanges();s.addRange(r)}refresh()}
function moveSection(from,to){const b=getBlocks();if(!b[from]||!b[to]||from===to)return;if(b[from].parentElement!==b[to].parentElement){toast('These blocks have different containers. Move them inside the document.');return}flush();b[to].parentElement.insertBefore(b[from],from<to?b[to].nextSibling:b[to]);selected=to;dirty=true;snapshot();refresh()}
function applySettings(record=true){for(const id of ['mt','mb','ml','mr','line','gap'])$(id).value=settings[id];$('cjk').checked=settings.cjk;$('line-value').textContent=Number(settings.line).toFixed(2).replace(/0$/,'');$('gap-value').textContent=settings.gap+' pt';$('single').classList.toggle('active',settings.columns===1);$('columns').classList.toggle('active',settings.columns===2);doc().getElementById('atelier-page-style').textContent=pageCSS();if(record){dirty=true;snapshot()}measure()}
function measure(){if(!root())return;const p=doc().getElementById('cv-page'),height=Math.max(1122.52,p.scrollHeight,p.getBoundingClientRect().height);frame.style.width='793.7px';frame.style.height=height+'px';frame.style.transform=`scale(${zoom})`;$('paper-wrap').style.width=793.7*zoom+'px';$('paper-wrap').style.height=height*zoom+22+'px';$('zoom-reset').textContent=Math.round(zoom*100)+'%';const text=root().innerText;const cjk=(text.match(/[\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]/g)||[]).length;const words=text.replace(/[\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]/g,' ').trim().split(/\s+/).filter(Boolean).length;$('word-count').textContent=`${words} words${cjk?' · '+cjk+' CJK characters':''}`;let overflow=height>1125||root().scrollWidth>root().clientWidth+2;$('health').classList.toggle('warning',overflow);$('health-title').textContent=overflow?'Check page fit':'Room to breathe';$('health-text').textContent=overflow?'Content exceeds one A4 page. Review page breaks in print preview.':'Your CV fits on one A4 page.';$('doc-status').textContent=dirty?'Edited · save to keep changes':'Ready to edit'}
function fit(){zoom=Math.min(1,Math.max(.2,($('canvas').clientWidth-(innerWidth<=600?24:60))/793.7));measure()}
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),4200)}
function sanitize(html){const p=new DOMParser().parseFromString(html,'text/html');p.querySelectorAll('script,iframe,object,embed,base,meta[http-equiv],form,input,button,textarea,select').forEach(el=>el.remove());p.querySelectorAll('*').forEach(el=>{for(const a of [...el.attributes]){if(/^on/i.test(a.name)||a.name==='srcdoc'||((/^(href|src|action|xlink:href)$/i.test(a.name))&&/^\s*(javascript|vbscript):/i.test(a.value)))el.removeAttribute(a.name)}el.removeAttribute('contenteditable')});return p}
async function importFile(file){if(!file)return;if(file.size>8*1024*1024){toast('Please use an HTML file smaller than 8 MB.');return}if(!/\.html?$/i.test(file.name)){toast('Choose an .html or .htm document.');return}if(dirty&&!confirm('Import a new CV? Unsaved changes in this tab will be replaced. Save HTML first if you need them.'))return;try{const p=sanitize(await file.text());const saved=p.querySelector('meta[name="atelier-settings"]');settings={mt:18,mb:18,ml:20,mr:20,line:1.5,gap:18,cjk:true,columns:1,font:'sans',size:11};if(saved){try{const v=JSON.parse(saved.content);for(const k of ['mt','mb','ml','mr'])settings[k]=Math.max(5,Math.min(45,Number(v[k])||settings[k]));settings.line=Math.max(1.1,Math.min(2,Number(v.line)||1.5));settings.gap=Math.max(4,Math.min(32,Number(v.gap)||18));settings.columns=v.columns===2?2:1;settings.cjk=v.cjk!==false;settings.font=fonts[v.font]?v.font:'sans';settings.size=Math.max(6,Math.min(72,Number(v.size)||11))}catch{}}p.querySelector('#atelier-page-style')?.remove();let styles=[...p.head.querySelectorAll('style,link[rel="stylesheet"]')].map(x=>x.outerHTML).join('');const original=p.querySelector('#cv-content')||p.body;const holder=p.createElement('div');for(const attr of ['style','class','dir','lang'])if(original.hasAttribute(attr))holder.setAttribute(attr,original.getAttribute(attr));let attrs=holder.outerHTML.match(/^<div(.*?)>/s)[1];dirty=false;selected=-1;$('filename').value=file.name.replace(/\.html?$/i,'');load(original.innerHTML,styles,attrs);frame.addEventListener('load',()=>{applySettings(false);toast('HTML imported. Review fonts, images, and page fit.');},{once:true})}catch{toast('This HTML file could not be opened.')}finally{$('file').value=''}}
function serialized(){const clone=doc().documentElement.cloneNode(true);clone.querySelectorAll('[contenteditable]').forEach(x=>x.removeAttribute('contenteditable'));clone.querySelectorAll('[data-active-section]').forEach(x=>x.removeAttribute('data-active-section'));clone.querySelectorAll('meta[name="atelier-settings"]').forEach(x=>x.remove());const meta=doc().createElement('meta');meta.name='atelier-settings';meta.content=JSON.stringify(settings);clone.querySelector('head').append(meta);const title=doc().createElement('title');title.textContent=$('filename').value||'Curriculum vitae';clone.querySelectorAll('title').forEach(x=>x.remove());clone.querySelector('head').append(title);return '<!doctype html>'+clone.outerHTML}
function download(){flush();const url=URL.createObjectURL(new Blob([serialized()],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=($('filename').value.replace(/[^\p{L}\p{N} ._-]/gu,'').trim()||'curriculum-vitae')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);dirty=false;measure();toast('HTML saved with your styles and page settings.')}
$('import').onclick=()=>$('file').click();$('file').onchange=e=>importFile(e.target.files[0]);$('download').onclick=download;$('undo').onclick=()=>undo(-1);$('redo').onclick=()=>undo(1);document.querySelectorAll('[data-cmd]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>command(b.dataset.cmd)});$('font').onchange=e=>{styleText('fontFamily',fonts[e.target.value])};$('size').onchange=e=>{styleText('fontSize',e.target.value+'pt')};$('color').oninput=e=>styleText('color',e.target.value);$('block').onchange=e=>command('formatBlock',e.target.value);
for(const id of ['mt','mb','ml','mr','line','gap'])$(id).onchange=e=>{flush();const min=Number(e.target.min),max=Number(e.target.max);settings[id]=Math.min(max,Math.max(min,Number(e.target.value)||min));applySettings()};$('cjk').onchange=e=>{flush();settings.cjk=e.target.checked;applySettings()};$('balanced').onclick=()=>{flush();Object.assign(settings,{mt:18,mb:18,ml:20,mr:20});applySettings()};$('single').onclick=()=>{flush();settings.columns=1;applySettings()};$('columns').onclick=()=>{flush();settings.columns=2;applySettings()};$('add').onclick=()=>{flush();const section=doc().createElement('section');section.innerHTML='<h2>New section</h2><p>Add your experience here.</p>';root().append(section);dirty=true;snapshot();refresh();selectSection(getBlocks().length-1,true)};$('guide').onclick=()=>$('help').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('export').onclick=()=>$('print-dialog').showModal();$('print-now').onclick=async()=>{$('print-dialog').close();toast('Preparing fonts and images for print…');await doc().fonts.ready;await Promise.all([...doc().images].map(img=>img.complete?Promise.resolve():Promise.race([new Promise(r=>{img.addEventListener('load',r,{once:true});img.addEventListener('error',r,{once:true})}),new Promise(r=>setTimeout(r,4000))])));const old=document.title;document.title=$('filename').value;doc().title=$('filename').value;frame.contentWindow.focus();frame.contentWindow.print();document.title=old};$('zoom-out').onclick=()=>{zoom=Math.max(.2,zoom-.1);measure()};$('zoom-in').onclick=()=>{zoom=Math.min(1.5,zoom+.1);measure()};$('zoom-reset').onclick=()=>{zoom=1;measure()};$('fit').onclick=fit;window.addEventListener('resize',fit);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();download()}});load(sample,`<style>${defaultCSS}</style>`);
